@import "tailwindcss";

@theme inline {
  --color-white: #ffffff;
  --color-darker: #2a2826;
  --color-teal: #5cb8a8;
  --color-teal-soft: rgba(92, 184, 168, 0.2);
  --color-overlay-50: rgba(42, 40, 38, 0.5);
  --color-overlay-75: rgba(42, 40, 38, 0.75);
  --color-price: #020704;
  --color-star: #ffcc00;

  --font-sans: var(--font-jakarta);
  --font-display: var(--font-lora);

  --radius-card: 16px;
  --radius-btn: 24px;

  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.05);

  --text-eyebrow: 0.3em;

  --breakpoint-3xl: 1920px;
}

:root {
  color-scheme: dark;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  background: #2a2826;
  color: #ffffff;
  font-family: var(--font-jakarta), Arial, Helvetica, sans-serif;
  overflow-x: hidden;
}

::selection {
  background: rgba(92, 184, 168, 0.35);
  color: #ffffff;
}

:focus-visible {
  outline: 2px solid var(--color-teal);
  outline-offset: 3px;
  border-radius: 4px;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

import type { Metadata } from "next";
import { Lora, Plus_Jakarta_Sans } from "next/font/google";
import "./globals.css";

const lora = Lora({
  variable: "--font-lora",
  subsets: ["latin"],
  weight: ["500", "600", "700"],
  display: "swap",
});

const jakarta = Plus_Jakarta_Sans({
  variable: "--font-jakarta",
  subsets: ["latin"],
  weight: ["300", "400", "500", "600", "700"],
  display: "swap",
});

export const metadata: Metadata = {
  title: "MentalZee — Find Calm, Build Balance, Live Better",
  description:
    "A peaceful space to care for your mind through personalized guidance, mindfulness, and professional support.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${lora.variable} ${jakarta.variable} h-full antialiased`}
    >
      <body className="min-h-full bg-darker text-white font-sans antialiased">
        {children}
      </body>
    </html>
  );
}

import type { Variants } from "framer-motion";

export const easeOutExpo: [number, number, number, number] = [0.16, 1, 0.3, 1];
export const easeInOut: [number, number, number, number] = [0.65, 0, 0.35, 1];

export const fadeUp: Variants = {
  hidden: { opacity: 0, y: 28 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.7, ease: easeOutExpo },
  },
};

export const fadeDown: Variants = {
  hidden: { opacity: 0, y: -24 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.7, ease: easeOutExpo },
  },
};

export const fadeIn: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0.8, ease: easeOutExpo } },
};

export const scaleIn: Variants = {
  hidden: { opacity: 0, scale: 0.9 },
  visible: {
    opacity: 1,
    scale: 1,
    transition: { duration: 0.6, ease: easeOutExpo },
  },
};

export const staggerContainer: Variants = {
  hidden: {},
  visible: {
    transition: { staggerChildren: 0.12, delayChildren: 0.1 },
  },
};

export const staggerFast: Variants = {
  hidden: {},
  visible: {
    transition: { staggerChildren: 0.08, delayChildren: 0.05 },
  },
};

export const viewportOnce = { once: true, margin: "-80px" } as const;

import { cn } from "@/lib/utils";

interface ContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  size?: "default" | "wide" | "narrow";
}

const sizes = {
  default: "max-w-[1280px]",
  wide: "max-w-[1360px]",
  narrow: "max-w-[768px]",
} as const;

export function Container({
  children,
  className,
  size = "default",
  ...props
}: ContainerProps) {
  return (
    <div
      className={cn(
        "mx-auto w-full px-6 sm:px-8 md:px-10 lg:px-12",
        sizes[size],
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

import { cn } from "@/lib/utils";

type SectionTitleProps = {
  eyebrow?: string;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  align?: "left" | "center";
  className?: string;
  titleClassName?: string;
};

export function SectionTitle({
  eyebrow,
  title,
  subtitle,
  align = "left",
  className,
  titleClassName,
}: SectionTitleProps) {
  const centered = align === "center";
  return (
    <div
      className={cn(
        "flex flex-col gap-6",
        centered && "items-center text-center",
        className
      )}
    >
      {eyebrow ? (
        <span
          className={cn(
            "font-sans text-base font-light tracking-[0.3em] text-white/80 uppercase",
            centered && "tracking-[0.3em]"
          )}
        >
          {eyebrow}
        </span>
      ) : null}
      <div className={cn("flex flex-col gap-6", centered && "items-center")}>
        <h2
          className={cn(
            "font-display text-[2rem] leading-[1.2] font-semibold tracking-[-0.006em] text-white sm:text-4xl md:text-[2.5rem] lg:text-[2.75rem]",
            centered && "max-w-3xl",
            titleClassName
          )}
        >
          {title}
        </h2>
        {subtitle ? (
          <p
            className={cn(
              "font-sans text-lg font-normal leading-[1.5] text-white/85",
              centered ? "max-w-2xl" : "max-w-xl"
            )}
          >
            {subtitle}
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { motion, type HTMLMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

type ButtonVariant = "primary" | "outline" | "ghost" | "dark";
type ButtonSize = "sm" | "lg" | "block";

interface ButtonProps extends Omit<HTMLMotionProps<"button">, "children"> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  children: React.ReactNode;
  icon?: React.ReactNode;
  iconPosition?: "leading" | "trailing";
}

const base =
  "inline-flex items-center justify-center gap-2 rounded-full font-sans font-semibold whitespace-nowrap transition-colors duration-300 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal disabled:opacity-60 disabled:pointer-events-none select-none";

const variants: Record<ButtonVariant, string> = {
  primary:
    "bg-teal text-white border border-teal shadow-xs hover:bg-teal/90 hover:border-teal/90",
  outline:
    "bg-transparent text-teal border-2 border-teal shadow-xs hover:bg-teal/10",
  ghost: "bg-transparent text-white border border-white/20 hover:bg-white/10",
  dark: "bg-darker text-white border border-darker hover:bg-darker/80",
};

const sizes: Record<ButtonSize, string> = {
  sm: "text-xs px-3 h-11",
  lg: "text-base px-5 h-12",
  block: "text-base px-5 h-12 w-full",
};

export function Button({
  variant = "primary",
  size = "lg",
  className,
  children,
  icon,
  iconPosition = "trailing",
  ...props
}: ButtonProps) {
  return (
    <motion.button
      whileHover={{ scale: 1.03 }}
      whileTap={{ scale: 0.97 }}
      transition={{ type: "spring", stiffness: 400, damping: 22 }}
      className={cn(base, variants[variant], sizes[size], className)}
      {...props}
    >
      {icon && iconPosition === "leading" ? icon : null}
      <span className="leading-none">{children}</span>
      {icon && iconPosition === "trailing" ? icon : null}
    </motion.button>
  );
}

export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

