"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, Sprout } from "lucide-react";
import { cn } from "@/lib/utils";
import { fadeDown } from "@/lib/motion";

const links = [
  { label: "Home", href: "#home" },
  { label: "Features", href: "#features" },
  { label: "Pricing", href: "#pricing" },
  { label: "About Us", href: "#about" },
];

export function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <motion.header
      variants={fadeDown}
      initial="hidden"
      animate="visible"
      className="fixed inset-x-0 top-6 z-50 flex justify-center px-4"
    >
      <nav
        className={cn(
          "flex h-12 items-center gap-1 rounded-full border border-white/10 bg-overlay-75/80 px-1.5 backdrop-blur-xl transition-all duration-500 sm:gap-2",
          scrolled ? "shadow-lg shadow-black/30" : "shadow-xs"
        )}
      >
        {/* Logo mark */}
        <a
          href="#home"
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-teal text-white"
          aria-label="MentalZee home"
        >
          <Sprout className="h-4 w-4" strokeWidth={2.2} />
        </a>

        {/* Desktop links */}
        <ul className="hidden items-center gap-0.5 md:flex">
          {links.map((l) => (
            <li key={l.href}>
              <a
                href={l.href}
                className="rounded-full px-3 py-1.5 font-sans text-xs font-semibold text-white/85 transition-colors hover:bg-white/10 hover:text-white"
              >
                {l.label}
              </a>
            </li>
          ))}
        </ul>

        {/* CTA */}
        <a
          href="#contact"
          className="hidden rounded-full bg-teal px-3 py-2 font-sans text-xs font-semibold text-white shadow-xs transition-transform hover:scale-105 md:inline-block"
        >
          Let&apos;s Talk
        </a>

        {/* Mobile toggle */}
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className="flex h-9 w-9 items-center justify-center rounded-full text-white md:hidden"
          aria-label="Toggle menu"
          aria-expanded={open}
        >
          {open ? <X className="h-4 w-4" /> : <Menu className="h-4 w-4" />}
        </button>
      </nav>

      {/* Mobile sheet */}
      <AnimatePresence>
        {open ? (
          <motion.div
            initial={{ opacity: 0, y: -12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -12 }}
            transition={{ duration: 0.25 }}
            className="absolute inset-x-4 top-16 rounded-3xl border border-white/10 bg-overlay-75/95 p-4 backdrop-blur-xl md:hidden"
          >
            <ul className="flex flex-col gap-1">
              {links.map((l) => (
                <li key={l.href}>
                  <a
                    href={l.href}
                    onClick={() => setOpen(false)}
                    className="block rounded-2xl px-4 py-3 font-sans text-sm font-semibold text-white/90 hover:bg-white/10"
                  >
                    {l.label}
                  </a>
                </li>
              ))}
              <li>
                <a
                  href="#contact"
                  onClick={() => setOpen(false)}
                  className="mt-1 block rounded-2xl bg-teal px-4 py-3 text-center font-sans text-sm font-semibold text-white"
                >
                  Let&apos;s Talk
                </a>
              </li>
            </ul>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </motion.header>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { ArrowUpRight } from "lucide-react";
import { easeOutExpo, fadeUp, staggerContainer } from "@/lib/motion";

export function Hero() {
  const reduce = useReducedMotion();

  return (
    <section
      id="home"
      className="relative flex min-h-[824px] flex-col justify-center overflow-hidden"
    >
      {/* Background image with breathing zoom (signature element) */}
      <motion.div
        className="absolute inset-0 -z-10"
        initial={reduce ? { opacity: 0 } : { scale: 1.12, opacity: 0 }}
        animate={{ scale: reduce ? 1 : 1, opacity: 1 }}
        transition={
          reduce
            ? { duration: 1 }
            : { scale: { duration: 18, ease: "easeInOut", repeat: Infinity, repeatType: "reverse" }, opacity: { duration: 1.2, ease: easeOutExpo } }
        }
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src="/images/hero-bg.png"
          alt=""
          className="h-full w-full object-cover"
        />
        <div className="absolute inset-0 bg-overlay-50" />
      </motion.div>

      {/* Right-edge hairline rule like the Figma column */}
      <div className="absolute inset-y-0 right-0 w-px bg-white/10" />

      <div className="mx-auto flex w-full max-w-[1280px] flex-col gap-12 px-6 py-32 sm:px-10 md:px-12 lg:py-40">
        <motion.div
          variants={staggerContainer}
          initial="hidden"
          animate="visible"
          className="flex max-w-[560px] flex-col gap-8"
        >
          {/* Eyebrow */}
          <motion.span
            variants={fadeUp}
            className="font-sans text-base font-light tracking-[0.3em] text-white/85 uppercase"
          >
            Personalized Mental Healthcare
          </motion.span>

          {/* Headline */}
          <motion.h1
            variants={fadeUp}
            className="font-display text-[2.75rem] leading-[1.15] font-semibold tracking-[-0.01em] text-white sm:text-5xl md:text-[3.25rem] lg:text-[3.5rem]"
          >
            Find Calm, Build Balance,{" "}
            <span className="block text-teal">Live Better</span>
          </motion.h1>

          {/* Subtext */}
          <motion.p
            variants={fadeUp}
            className="max-w-[540px] font-sans text-lg font-medium leading-[1.5] text-white/85"
          >
            A peaceful space to care for your mind through personalized
            guidance, mindfulness, and professional support.
          </motion.p>

          {/* CTA pill */}
          <motion.div variants={fadeUp}>
            <motion.a
              href="#features"
              whileHover={{ scale: 1.04 }}
              whileTap={{ scale: 0.97 }}
              transition={{ type: "spring", stiffness: 400, damping: 22 }}
              className="group inline-flex h-12 items-center gap-2 rounded-full border border-teal bg-teal pl-4 pr-1.5 font-sans text-base font-semibold text-white shadow-xs transition-colors hover:bg-teal/90"
            >
              <span>Start Your Journey</span>
              <span className="flex h-9 w-10 items-center justify-center rounded-full bg-darker transition-transform duration-300 group-hover:translate-x-0.5 group-hover:-translate-y-0.5">
                <ArrowUpRight className="h-5 w-5" strokeWidth={2.2} />
              </span>
            </motion.a>
          </motion.div>
        </motion.div>
      </div>

      {/* Bottom "Calm & Peaceful" divider */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.1, duration: 0.8 }}
        className="absolute inset-x-0 bottom-8 flex items-center justify-center gap-3 px-10"
      >
        <span className="h-px flex-1 bg-white/20" />
        <span className="font-sans text-sm font-light tracking-[0.3em] text-white/75 uppercase">
          Calm &amp; Peaceful
        </span>
        <span className="h-px flex-1 bg-white/20" />
      </motion.div>
    </section>
  );
}

import { Navbar } from "@/components/layout/Navbar";
import { Hero } from "@/components/sections/Hero";

export default function Home() {
  return (
    <>
      <Navbar />
      <main>
        <Hero />
      </main>
    </>
  );
}

