"use client";

import { motion } from "framer-motion";
import {
  fadeUp,
  scaleIn,
  staggerContainer,
  staggerFast,
  viewportOnce,
} from "@/lib/motion";

type Tile = { src: string; tall?: boolean };

const rows: Tile[][] = [
  [
    { src: "/images/gallery-1.png", tall: true },
    { src: "/images/gallery-2.png", tall: true },
    { src: "/images/gallery-3.png" },
    { src: "/images/about-image.png" },
  ],
  [
    { src: "/images/gallery-4.png" },
    { src: "/images/gallery-5.png" },
    { src: "/images/gallery-6.png" },
    { src: "/images/gallery-7.png" },
  ],
];

export function Gallery() {
  return (
    <section className="relative bg-darker">
      <div className="mx-auto flex w-full max-w-[1280px] flex-col gap-8 px-6 py-24 sm:px-10 md:px-12 md:py-28 lg:py-32">
        {/* Title */}
        <motion.div
          variants={staggerContainer}
          initial="hidden"
          whileInView="visible"
          viewport={viewportOnce}
          className="flex flex-col gap-6"
        >
          <motion.h2
            variants={fadeUp}
            className="font-display text-[2rem] leading-[1.2] font-semibold tracking-[-0.006em] text-white sm:text-4xl md:text-[2.5rem] lg:text-[2.75rem]"
          >
            Image Gallery
          </motion.h2>
          <motion.p
            variants={fadeUp}
            className="max-w-2xl font-sans text-lg font-normal leading-[1.5] text-white/85"
          >
            A glimpse into the warm moments and connections built within our
            supportive community
          </motion.p>
        </motion.div>

        {/* Two rows of 4 tiles */}
        <div className="flex flex-col gap-8">
          {rows.map((row, ri) => (
            <motion.div
              key={ri}
              variants={staggerFast}
              initial="hidden"
              whileInView="visible"
              viewport={viewportOnce}
              className="grid grid-cols-2 gap-8 sm:grid-cols-4"
            >
              {row.map((tile, ti) => (
                <Tile key={`${ri}-${ti}`} tile={tile} />
              ))}
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}

function Tile({ tile }: { tile: Tile }) {
  return (
    <motion.figure
      variants={scaleIn}
      whileHover={{ y: -6 }}
      transition={{ type: "spring", stiffness: 300, damping: 24 }}
      className="group relative overflow-hidden rounded-[16px]"
    >
      <div
        className={[
          "relative w-full overflow-hidden",
